import { AgeGroup, Class, Dance, Discipline, EventKind, PayMethod, PaymentStatus, ProgramKind, Role, RoundStatus, RoundType } from '@bis/shared'
import type { AthleteNotification, CompetitorDetails, MembershipEvent, MembershipRequest, ProfileChangeRequest } from '@bis/shared'
import { index, integer, primaryKey, real, sqliteTable, text, uniqueIndex } from 'drizzle-orm/sqlite-core'

// Drizzle wants a non-empty tuple of the allowed strings
const oneOf = <T extends Record<string, string>>(values: T) =>
  Object.values(values) as [T[keyof T], ...Array<T[keyof T]>]

// Ids are generated by the app, not the database.
// Timestamps are ISO 8601 UTC strings; the server's clock is the source of truth on the day.
const id = () => text('id').primaryKey()

export const competitions = sqliteTable('competitions', {
  id: id(),
  name: text('name').notNull(),
  date: text('date').notNull(),
  venue: text('venue').notNull(),
  organizer: text('organizer').notNull(),
  // YYYY-MM-DD; after these an entry is late or unpaid
  entryDeadline: text('entry_deadline'),
  feeDeadline: text('fee_deadline'),
  // The photo on its home page card, as a data URL
  image: text('image'),
  // The round on the floor now; the scrutineer sets it
  floorRoundId: text('floor_round_id'),
})

// A team the secretariat enters dancers for; teams have no sign-in
export const teams = sqliteTable('teams', {
  id: id(),
  name: text('name').notNull(),
  contactName: text('contact_name').notNull().default(''),
  contactEmail: text('contact_email').notNull().default(''),
  contactPhone: text('contact_phone').notNull().default(''),
})

export const events = sqliteTable(
  'events',
  {
    id: id(),
    competitionId: text('competition_id')
      .notNull()
      .references(() => competitions.id, { onDelete: 'cascade' }),
    // E47 is number 47
    number: integer('number').notNull(),
    // 1 is first on the floor
    position: integer('position').notNull(),
    ageGroup: text('age_group', { enum: oneOf(AgeGroup) }).notNull(),
    class: text('class', { enum: oneOf(Class) }).notNull(),
    discipline: text('discipline', { enum: oneOf(Discipline) }).notNull(),
    dances: text('dances', { mode: 'json' }).$type<Dance[]>().notNull(),
    isSolo: integer('is_solo', { mode: 'boolean' }).notNull(),
    kind: text('kind', { enum: oneOf(EventKind) }).notNull().default('standard'),
    // The province a closed event is open to
    province: text('province').notNull().default(''),
  },
  (t) => [uniqueIndex('events_number_per_competition').on(t.competitionId, t.number)],
)

export const competitors = sqliteTable(
  'competitors',
  {
    id: id(),
    // A couple has two names; a solo dancer has one
    names: text('names', { mode: 'json' }).$type<string[]>().notNull(),
    // Worked out in the team's form from the dancers' birth years, which are not kept
    ageGroup: text('age_group', { enum: oneOf(AgeGroup) }),
    birthDate: text('birth_date'),
    // The rest of the entry form: province, coach, each dancer's details, beginner and membership
    details: text('details', { mode: 'json' }).$type<CompetitorDetails>(),
    // Null until the secretariat assigns one; unique once assigned
    backNumber: integer('back_number'),
    teamId: text('team_id')
      .notNull()
      .references(() => teams.id),
  },
  (t) => [uniqueIndex('competitors_back_number').on(t.backNumber), index('competitors_team').on(t.teamId)],
)

export interface PaymentSettles {
  year: number
  competitorId?: string
  coachId?: string
  coachMembership?: boolean
  coachSummit?: boolean
}

export const coaches = sqliteTable('coaches', {
  id: id(),
  name: text('name').notNull(),
  email: text('email').notNull().default(''),
  phone: text('phone').notNull().default(''),
  // The years the coach's membership and Coaches Summit were last paid for
  memberYear: integer('member_year'),
  summitYear: integer('summit_year'),
})

export const payments = sqliteTable('payments', {
  id: id(),
  teamId: text('team_id')
    .notNull()
    .references(() => teams.id),
  competitionId: text('competition_id').references(() => competitions.id, { onDelete: 'cascade' }),
  // A late entry at the venue has its own payment; the team's main payment covers its portal entries
  late: integer('late', { mode: 'boolean' }).notNull().default(false),
  amountDue: real('amount_due').notNull(),
  amountPaid: real('amount_paid'),
  referenceNumber: text('reference_number'),
  // How the secretariat was paid, when they recorded it
  method: text('method', { enum: oneOf(PayMethod) }),
  // What this payment settles once it is paid: an athlete's or a coach's membership for a year
  settles: text('settles', { mode: 'json' }).$type<PaymentSettles>(),
  // TODO: phase 6 stores receipts as private files on the cloud server; until then the screenshot is kept here as a data URL
  receipt: text('receipt'),
  status: text('status', { enum: oneOf(PaymentStatus) }).notNull(),
  rejectionReason: text('rejection_reason'),
  checkedBy: text('checked_by'),
  checkedAt: text('checked_at'),
})

export const entries = sqliteTable(
  'entries',
  {
    id: id(),
    eventId: text('event_id')
      .notNull()
      .references(() => events.id, { onDelete: 'cascade' }),
    competitorId: text('competitor_id')
      .notNull()
      .references(() => competitors.id, { onDelete: 'cascade' }),
    scratched: integer('scratched', { mode: 'boolean' }).notNull().default(false),
    paymentId: text('payment_id').references(() => payments.id),
    // Added at the venue after entries closed
    late: integer('late', { mode: 'boolean' }).notNull().default(false),
  },
  (t) => [
    uniqueIndex('entries_once_per_event').on(t.eventId, t.competitorId),
    index('entries_payment').on(t.paymentId),
  ],
)

export const adjudicators = sqliteTable(
  'adjudicators',
  {
    id: id(),
    name: text('name').notNull(),
    // A to J
    letter: text('letter').notNull(),
    // See staff_users: a new PIN sign-in raises it, so an adjudicator is signed in on one phone at a time
    sessionVersion: integer('session_version').notNull().default(0),
  },
  (t) => [uniqueIndex('adjudicators_letter').on(t.letter)],
)

export const adjudicatorPins = sqliteTable(
  'adjudicator_pins',
  {
    competitionId: text('competition_id')
      .notNull()
      .references(() => competitions.id, { onDelete: 'cascade' }),
    adjudicatorId: text('adjudicator_id')
      .notNull()
      .references(() => adjudicators.id, { onDelete: 'cascade' }),
    // Kept readable on purpose: the admin prints these on cards and must be able to reprint them
    pin: text('pin').notNull(),
  },
  (t) => [
    primaryKey({ columns: [t.competitionId, t.adjudicatorId] }),
    uniqueIndex('pins_unique_per_competition').on(t.competitionId, t.pin),
  ],
)

export const panels = sqliteTable('panels', {
  id: id(),
  eventId: text('event_id')
    .notNull()
    .unique()
    .references(() => events.id, { onDelete: 'cascade' }),
})

export const panelMembers = sqliteTable(
  'panel_members',
  {
    panelId: text('panel_id')
      .notNull()
      .references(() => panels.id, { onDelete: 'cascade' }),
    adjudicatorId: text('adjudicator_id')
      .notNull()
      .references(() => adjudicators.id, { onDelete: 'cascade' }),
  },
  (t) => [primaryKey({ columns: [t.panelId, t.adjudicatorId] })],
)

export const rounds = sqliteTable(
  'rounds',
  {
    id: id(),
    eventId: text('event_id')
      .notNull()
      .references(() => events.id, { onDelete: 'cascade' }),
    type: text('type', { enum: oneOf(RoundType) }).notNull(),
    // Order within the event, 1 first
    position: integer('position').notNull(),
    // How many each adjudicator marks X; null for the final
    recallNumber: integer('recall_number'),
    status: text('status', { enum: oneOf(RoundStatus) }).notNull(),
    // When the scrutineer published it; the MC reads announcements in this order
    publishedAt: text('published_at'),
  },
  (t) => [uniqueIndex('rounds_once_per_event').on(t.eventId, t.type)],
)

// The running order: rounds, breaks and awarding in the order they are danced. A round slot names an event and a round
// type rather than a round row, because rounds only exist once the scrutineer has planned them.
export const programSlots = sqliteTable(
  'program_slots',
  {
    id: id(),
    competitionId: text('competition_id')
      .notNull()
      .references(() => competitions.id, { onDelete: 'cascade' }),
    // 1 is first; renumbered from 1 after every change
    sequence: integer('sequence').notNull(),
    kind: text('kind', { enum: oneOf(ProgramKind) }).notNull(),
    eventId: text('event_id').references(() => events.id, { onDelete: 'cascade' }),
    roundType: text('round_type', { enum: oneOf(RoundType) }),
    // Names a break or the awarding
    label: text('label'),
    minutes: integer('minutes').notNull(),
  },
  (t) => [index('program_slots_order').on(t.competitionId, t.sequence)],
)

// When a competition's running order starts, "HH:MM"; each slot's time is worked out from it. One row at most per
// competition. It is a table of its own, not a column, so it travels to the cloud with the slots.
export const programStarts = sqliteTable('program_starts', {
  competitionId: text('competition_id')
    .primaryKey()
    .references(() => competitions.id, { onDelete: 'cascade' }),
  start: text('start').notNull(),
})

export const heats = sqliteTable(
  'heats',
  {
    id: id(),
    roundId: text('round_id')
      .notNull()
      .references(() => rounds.id, { onDelete: 'cascade' }),
    number: integer('number').notNull(),
  },
  (t) => [uniqueIndex('heats_number_per_round').on(t.roundId, t.number)],
)

export const heatCompetitors = sqliteTable(
  'heat_competitors',
  {
    heatId: text('heat_id')
      .notNull()
      .references(() => heats.id, { onDelete: 'cascade' }),
    competitorId: text('competitor_id')
      .notNull()
      .references(() => competitors.id),
  },
  (t) => [primaryKey({ columns: [t.heatId, t.competitorId] })],
)

// One row per adjudicator per round. All of an adjudicator's marks arrive together, so this means "submitted"
export const submissions = sqliteTable(
  'submissions',
  {
    roundId: text('round_id')
      .notNull()
      .references(() => rounds.id, { onDelete: 'cascade' }),
    adjudicatorId: text('adjudicator_id')
      .notNull()
      .references(() => adjudicators.id),
    submittedAt: text('submitted_at').notNull(),
    // Set when the scrutineer typed the marks in from a paper sheet
    enteredBy: text('entered_by'),
    // The adjudicator's drawn signature as a PNG data URL; none for marks typed in from paper
    signature: text('signature'),
  },
  (t) => [primaryKey({ columns: [t.roundId, t.adjudicatorId] })],
)

export const marks = sqliteTable(
  'marks',
  {
    id: id(),
    roundId: text('round_id')
      .notNull()
      .references(() => rounds.id, { onDelete: 'cascade' }),
    adjudicatorId: text('adjudicator_id')
      .notNull()
      .references(() => adjudicators.id),
    competitorId: text('competitor_id')
      .notNull()
      .references(() => competitors.id),
    dance: text('dance', { enum: oneOf(Dance) }).notNull(),
    kind: text('kind', { enum: ['x', 'placing'] }).notNull(),
    // Set when kind is placing
    placing: integer('placing'),
    // Server clock, so a wrong phone clock cannot reorder anything
    submittedAt: text('submitted_at').notNull(),
  },
  // Write-once: a repeated submission after a dropped connection cannot add a second mark
  (t) => [uniqueIndex('marks_once').on(t.roundId, t.adjudicatorId, t.competitorId, t.dance)],
)

export const tieDecisions = sqliteTable('tie_decisions', {
  roundId: text('round_id')
    .primaryKey()
    .references(() => rounds.id, { onDelete: 'cascade' }),
  // Recall everyone on the tie, or only those above it
  choice: text('choice', { enum: ['more', 'fewer'] }).notNull(),
  proposedBy: text('proposed_by').notNull(),
  proposedAt: text('proposed_at').notNull(),
  confirmedBy: text('confirmed_by'),
  confirmedAt: text('confirmed_at'),
})

// A tie in a final that the Skating System leaves as a shared place. The chairperson decides: keep it shared, or settle
// it with a tie-break (an extra dance) whose order the scrutineer types in.
export const finalTieDecisions = sqliteTable('final_tie_decisions', {
  roundId: text('round_id')
    .primaryKey()
    .references(() => rounds.id, { onDelete: 'cascade' }),
  mode: text('mode', { enum: ['keep', 'order'] }).notNull(),
  // For 'order': the tied competitors, best first
  order: text('order', { mode: 'json' }).$type<string[]>().notNull(),
  proposedBy: text('proposed_by').notNull(),
  proposedAt: text('proposed_at').notNull(),
  confirmedBy: text('confirmed_by'),
  confirmedAt: text('confirmed_at'),
})

export const results = sqliteTable(
  'results',
  {
    id: id(),
    eventId: text('event_id')
      .notNull()
      .references(() => events.id, { onDelete: 'cascade' }),
    competitorId: text('competitor_id')
      .notNull()
      .references(() => competitors.id),
    // The best place of a shared range, as the MC reads it (the 13 in 13th to 18th)
    place: integer('place').notNull(),
    // The whole shared range; equal when the place is not shared
    placeFrom: integer('place_from').notNull(),
    placeTo: integer('place_to').notNull(),
    // Where the competitor went out: the final, or the round that cut them. Ranking points depend on it
    stage: text('stage', { enum: oneOf(RoundType) }).notNull(),
    approvedBy: text('approved_by').notNull(),
    approvedAt: text('approved_at').notNull(),
  },
  (t) => [uniqueIndex('results_once_per_event').on(t.eventId, t.competitorId)],
)

export const pointsTable = sqliteTable('points_table', {
  id: id(),
  // 1 to 7; null is a row for everyone cut in a round
  place: integer('place'),
  // The round of such a row: 'semi_final' or 'quarter_final'; null counts as the semi-final
  round: text('round', { enum: ['semi_final', 'quarter_final'] }),
  label: text('label').notNull(),
  points: real('points').notNull(),
  sortOrder: integer('sort_order').notNull(),
})

export const rankingPoints = sqliteTable(
  'ranking_points',
  {
    id: id(),
    competitorId: text('competitor_id')
      .notNull()
      .references(() => competitors.id),
    ageGroup: text('age_group', { enum: oneOf(AgeGroup) }).notNull(),
    class: text('class', { enum: oneOf(Class) }).notNull(),
    discipline: text('discipline', { enum: oneOf(Discipline) }).notNull(),
    competitionId: text('competition_id')
      .notNull()
      .references(() => competitions.id, { onDelete: 'cascade' }),
    eventId: text('event_id')
      .notNull()
      .references(() => events.id, { onDelete: 'cascade' }),
    points: real('points').notNull(),
  },
  (t) => [
    uniqueIndex('ranking_points_once_per_event').on(t.eventId, t.competitorId),
    index('ranking_points_category').on(t.ageGroup, t.class, t.discipline),
  ],
)

export const staffUsers = sqliteTable('staff_users', {
  id: id(),
  name: text('name').notNull(),
  username: text('username').notNull().unique(),
  role: text('role', { enum: oneOf(Role) }).notNull(),
  passwordHash: text('password_hash').notNull(),
  disabled: integer('disabled', { mode: 'boolean' }).notNull().default(false),
  // A signed token carries the version it was made at; raising it signs the person out everywhere
  sessionVersion: integer('session_version').notNull().default(0),
  // Two-step sign-in: the shared secret of an authenticator app (base32). It is only asked for once totpEnabled is set,
  // after the person has proved they hold the app by typing a code from it.
  totpSecret: text('totp_secret'),
  totpEnabled: integer('totp_enabled', { mode: 'boolean' }).notNull().default(false),
  // The last 30-second step a code was accepted for, so a code cannot be used twice
  totpLastStep: integer('totp_last_step').notNull().default(0),
  // Hashes of the recovery codes still unused (JSON list); a code is shown once, when two-step is turned on
  totpRecovery: text('totp_recovery', { mode: 'json' }).$type<string[]>().notNull().default([]),
})

// An athlete's own account: they sign in with their email and keep their details and membership here
export const athletes = sqliteTable('athletes', {
  id: id(),
  name: text('name').notNull(),
  email: text('email').notNull().unique(),
  passwordHash: text('password_hash').notNull(),
  birthDate: text('birth_date').notNull().default(''),
  phone: text('phone').notNull().default(''),
  address: text('address').notNull().default(''),
  province: text('province').notNull().default(''),
  teamId: text('team_id').references(() => teams.id, { onDelete: 'set null' }),
  coachId: text('coach_id').references(() => coaches.id, { onDelete: 'set null' }),
  // The year the membership was last paid for; set when the secretariat confirms a request
  memberYear: integer('member_year'),
  request: text('request', { mode: 'json' }).$type<MembershipRequest>(),
  // See staff_users: raising it signs the athlete out everywhere
  sessionVersion: integer('session_version').notNull().default(0),
  // A small picture as a data URL
  photo: text('photo'),
  // Every payment sent, confirmed or turned down, oldest first
  membershipHistory: text('membership_history', { mode: 'json' }).$type<MembershipEvent[]>().notNull().default([]),
  // A team or coach change waiting for the secretariat
  changeRequest: text('change_request', { mode: 'json' }).$type<ProfileChangeRequest>(),
})

// A coach's or a team's own account. Athletes keep their own table; these two only sign in and see their page.
export const memberAccounts = sqliteTable('member_accounts', {
  id: id(),
  role: text('role', { enum: ['coach', 'team'] }).notNull(),
  name: text('name').notNull(),
  email: text('email').notNull().unique(),
  passwordHash: text('password_hash').notNull(),
  phone: text('phone').notNull().default(''),
  birthDate: text('birth_date').notNull().default(''),
  province: text('province').notNull().default(''),
  address: text('address').notNull().default(''),
  // A small picture as a data URL
  photo: text('photo'),
  sessionVersion: integer('session_version').notNull().default(0),
  // The coach or team record this account stands for, set when the secretariat approves a claim
  linkedId: text('linked_id'),
  // A coach or team the account asked to be linked to, waiting for the secretariat
  claimId: text('claim_id'),
  claimedAt: text('claimed_at'),
})

// A team's (or an athlete's) request to enter a dancer or couple in events, with the payment already made. The secretariat
// checks the screenshot and approves it, which creates the entries and the payment.
export const entryRequests = sqliteTable(
  'entry_requests',
  {
    id: id(),
    requesterId: text('requester_id').notNull(),
    requesterRole: text('requester_role', { enum: ['team', 'athlete'] }).notNull(),
    requesterName: text('requester_name').notNull(),
    competitorId: text('competitor_id')
      .notNull()
      .references(() => competitors.id, { onDelete: 'cascade' }),
    competitionId: text('competition_id')
      .notNull()
      .references(() => competitions.id, { onDelete: 'cascade' }),
    eventIds: text('event_ids', { mode: 'json' }).$type<string[]>().notNull(),
    total: real('total').notNull(),
    warnings: text('warnings', { mode: 'json' }).$type<string[]>().notNull().default([]),
    method: text('method').$type<PayMethod>().notNull(),
    reference: text('reference').notNull().default(''),
    // TODO: phase 6 stores receipts as private files on the cloud server; until then the screenshot is kept here as a data URL
    receipt: text('receipt').notNull(),
    status: text('status', { enum: ['waiting', 'approved', 'rejected'] }).notNull().default('waiting'),
    rejectedReason: text('rejected_reason'),
    createdAt: text('created_at').notNull(),
    decidedAt: text('decided_at'),
    decidedBy: text('decided_by'),
  },
  (t) => [index('entry_requests_by_requester').on(t.requesterId, t.createdAt), index('entry_requests_by_status').on(t.status)],
)

// What the system tells a coach or a team: whether the secretariat linked their account to a record
export const memberNotifications = sqliteTable(
  'member_notifications',
  {
    id: id(),
    memberId: text('member_id')
      .notNull()
      .references(() => memberAccounts.id, { onDelete: 'cascade' }),
    kind: text('kind').$type<AthleteNotification['kind']>().notNull(),
    title: text('title').notNull(),
    detail: text('detail').notNull().default(''),
    link: text('link'),
    createdAt: text('created_at').notNull(),
    readAt: text('read_at'),
  },
  (t) => [index('member_notifications_by_member').on(t.memberId, t.createdAt)],
)

// What the system tells an athlete; the bell in their navbar and the Notifications page read these
export const notifications = sqliteTable(
  'notifications',
  {
    id: id(),
    athleteId: text('athlete_id')
      .notNull()
      .references(() => athletes.id, { onDelete: 'cascade' }),
    kind: text('kind').$type<AthleteNotification['kind']>().notNull(),
    title: text('title').notNull(),
    detail: text('detail').notNull().default(''),
    link: text('link'),
    createdAt: text('created_at').notNull(),
    readAt: text('read_at'),
  },
  (t) => [index('notifications_by_athlete').on(t.athleteId, t.createdAt)],
)

export const auditLog = sqliteTable(
  'audit_log',
  {
    id: id(),
    actorId: text('actor_id').notNull(),
    action: text('action').notNull(),
    target: text('target').notNull(),
    // What the record looked like before and after, as JSON
    before: text('before', { mode: 'json' }),
    after: text('after', { mode: 'json' }),
    at: text('at').notNull(),
  },
  (t) => [index('audit_log_at').on(t.at)],
)

// Small server settings kept in the database, so a restored backup carries them: the key that signs sign-in cookies
export const settings = sqliteTable('settings', {
  key: text('key').primaryKey(),
  value: text('value').notNull(),
})
